module sync_data_ram #(
    parameter C_PROGRAM = 0,
    parameter COREMARK_PROGRAM = 0,
    parameter COREMARK_FILE = 0,
    parameter integer WORDS = 256,
    parameter integer ADDR_BITS = 8
)(
    input wire clk,
    input wire reset,
    
    input wire mem_valid,//CPU正在提出一个有效的访存请求
    input wire mem_write,//0表示从内存读取到CPU，1表示从CPU存到内存
    input wire[3:0] mem_wstrb,//字节写使能
    input wire[31:0] mem_addr,//CPU想访问的字节地址
    input wire[31:0] mem_wdata,//CPU要写入内存的数据

    output wire mem_ready,//内存已经完成当前请求，CPU可以接收结果并继续运行
    output reg[31:0] mem_rdata//内存返回给CPU的数据
);

reg[31:0] mem[0:WORDS-1]; // CoreMark 模式为 16384 个 word，即 64 KiB。

// 只在 FPGA 配置/仿真开始时预装；按钮复位不重新装载 RAM。
// start.S 每次复位从保留副本恢复 .data，并清零 .bss。
generate
    if (COREMARK_PROGRAM) begin : g_coremark_initial_data
        initial begin
            // 内置镜像包含全部 16384 个 word（含零值），不使用大循环。
            if (COREMARK_FILE) begin
                $readmemh("coremark_data.hex", mem);
            end else begin
    // BEGIN GENERATED COREMARK RAM
                mem[0] = 32'h00000000;
                mem[1] = 32'h00000000;
                mem[2] = 32'h00000000;
                mem[3] = 32'h00000000;
                mem[4] = 32'h00000000;
