localparam IDLE = 1'b0;//空闲状态
localparam RESP = 1'b1;//响应状态

reg state;

wire[ADDR_BITS-1:0] word_index;//RAM中第几个32位word
assign word_index = mem_addr[ADDR_BITS+1:2];

assign mem_ready = (state == RESP);

always@(posedge clk)begin
    
    if(reset)begin
        state<=IDLE;
        mem_rdata<=32'b0;
    end
    else begin
        case(state)
            IDLE:begin
                if(mem_valid)begin
                    if(mem_write)begin
                        if(mem_wstrb[0])
                            mem[word_index][7:0]<=mem_wdata[7:0];
                        if (mem_wstrb[1])
                            mem[word_index][15:8]<= mem_wdata[15:8];
                        if (mem_wstrb[2])
                            mem[word_index][23:16]<= mem_wdata[23:16];
                        if (mem_wstrb[3])
                            mem[word_index][31:24]<= mem_wdata[31:24];
                    end
                    else begin
                        mem_rdata<=mem[word_index];
                    end

                    state<=RESP;
                end
            end

            RESP:begin
                state<=IDLE;
            end

            default:begin
                state<=IDLE;
            end
        endcase
    end
end

endmodule
